 10 | func newErr(status int, code, message string) error {
 11 | 	return apierr.New(status, code, message)
 12 | }
 13 | 
 14 | func wrapErr(err error, status int, code, message string) error {
 15 | 	return apierr.Wrap(err, status, code, message)
 16 | }
 17 | 
 18 | // newRetryErr builds a 429 that also tells the client when to come back.
 19 | func newRetryErr(code, message string, retryAfter int) error {
 20 | 	e := apierr.New(http.StatusTooManyRequests, code, message)
 21 | 	e.RetryAfter = retryAfter
 22 | 	return e
 23 | }
 24 | 
 25 | // Stable machine-readable error codes returned in `error.code`. The admin
 26 | // panel switches on these instead of parsing messages.
 27 | const (
 28 | 	CodeInvalidCredentials = "invalid_credentials"
 29 | 	CodeAccountDisabled    = "account_disabled"
 30 | 	CodeRateLimited        = "too_many_attempts"
 31 | 
 32 | 	CodeInvalidChallenge = "invalid_challenge"
 33 | 	CodeChallengeExpired = "challenge_expired"
 34 | 	CodeChallengeUsed    = "challenge_already_used"
 35 | 	CodeInvalidOTP       = "invalid_otp"
 36 | 	CodeOTPAttempts      = "otp_attempts_exceeded"
 37 | 	CodeOTPTooMany       = "otp_too_many_requests"
 38 | 	CodeOTPCooldown      = "otp_resend_cooldown"
 39 | 
 40 | 	CodeInvalidRefreshToken = "invalid_refresh_token"
 41 | 	CodeRefreshTokenReused  = "refresh_token_reused"
 42 | 
 43 | 	CodeEmailDeliveryFailed = "email_delivery_failed"
 44 | 	CodeTwoFAEnforced       = "two_factor_enforced"
 45 | 	CodeTwoFANotConfigured  = "two_factor_not_configured"
