 15 | // pruneOlderThan is the retention window for expired OTP challenges and
 16 | // revoked/expired refresh tokens (housekeeping only — they are never valid
 17 | // after their own expiry).
 18 | const pruneOlderThan = 7 * 24 * time.Hour
 19 | 
 20 | // adminFor loads an admin and maps "missing row" to invalid credentials, so an
 21 | // endpoint never confirms that an account was deleted.
 22 | func (s *AuthService) adminFor(ctx context.Context, adminID string) (*models.AdminUser, error) {
 23 | 	admin, err := s.admins.FindByID(ctx, adminID)
 24 | 	if err != nil {
 25 | 		if errors.Is(err, models.ErrNotFound) {
 26 | 			return nil, errInvalidCredentials()
 27 | 		}
 28 | 		return nil, err
 29 | 	}
 30 | 	return admin, nil
 31 | }
