 33 | // adminView projects the account to its public shape.
 34 | func adminView(a *models.AdminUser) *AdminView {
 35 | 	if a == nil {
 36 | 		return nil
 37 | 	}
 38 | 	return &AdminView{
 39 | 		ID:          a.ID,
 40 | 		Username:    a.Username,
 41 | 		Email:       a.Email,
 42 | 		IsActive:    a.IsActive,
 43 | 		LastLoginAt: a.LastLoginAt,
 44 | 	}
