 47 | // auditEvent writes an audit_log row. Failures are logged but never bubble up:
 48 | // authentication must not depend on the audit table being writable.
 49 | func (s *AuthService) auditEvent(ctx context.Context, adminID, action, reason string, extra map[string]any) {
 50 | 	payload := map[string]any{}
 51 | 	if reason != "" {
 52 | 		payload["reason"] = reason
 53 | 	}
 54 | 	for k, v := range extra {
 55 | 		payload[k] = v
 56 | 	}
 57 | 
 58 | 	newValue := ""
 59 | 	if len(payload) > 0 {
 60 | 		if encoded, err := json.Marshal(payload); err == nil {
 61 | 			newValue = string(encoded)
 62 | 		}
 63 | 	}
 64 | 
 65 | 	entry := &models.AuditEntry{
 66 | 		ID:         ids.New(),
 67 | 		AdminID:    adminID,
 68 | 		EntityType: models.EntityAuth,
 69 | 		Action:     action,
 70 | 		NewValue:   newValue,
 71 | 		CreatedAt:  s.now(),
 72 | 	}
 73 | 	if err := s.audit.Insert(ctx, entry); err != nil {
 74 | 		log.Printf("⚠️  auth: audit insert failed (%s): %v", action, err)
 75 | 	}
 76 | }
