 78 | // pruneExpired deletes stale rows in the background. It intentionally runs
 79 | // detached from the request so a cleanup failure can never fail a login.
 80 | func (s *AuthService) pruneExpired(ctx context.Context) {
 81 | 	cutoff := s.now().Add(-pruneOlderThan)
 82 | 	cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 10*time.Second)
