 13 | // emailTwoFAConfig resolves whether email OTP must be used for this admin.
 14 | //
 15 | // Rules:
 16 | //   - a row with is_enabled = 1 means 2FA is on;
 17 | //   - when AUTH_2FA_REQUIRED=true the second factor can never be skipped: a
 18 | //     missing row is auto-provisioned (no enrollment is needed for email OTP)
 19 | //     and a disabled row is re-enabled;
 20 | //   - when AUTH_2FA_REQUIRED=false the admin's own setting decides.
 21 | //
 22 | // The bool return value reports whether an OTP must be sent.
 23 | func (s *AuthService) emailTwoFAConfig(ctx context.Context, admin *models.AdminUser) (*models.TwoFactorConfig, bool, error) {
 24 | 	cfg, err := s.twoFA.FindByAdminAndMethod(ctx, admin.ID, models.TwoFAMethodEmailOTP)
 25 | 	switch {
 26 | 	case err == nil:
 27 | 		if cfg.IsEnabled {
 28 | 			return cfg, true, nil
 29 | 		}
 30 | 		if !s.cfg.TwoFARequired {
 31 | 			return cfg, false, nil
 32 | 		}
 33 | 
 34 | 		now := s.now()
 35 | 		cfg.IsEnabled = true
 36 | 		cfg.ConfirmedAt = &now
 37 | 		if err := s.twoFA.SetEnabled(ctx, admin.ID, cfg.Method, true, now); err != nil {
 38 | 			return nil, false, err
 39 | 		}
 40 | 		s.auditEvent(ctx, admin.ID, models.AuditTwoFAEnabled, "enforced_by_config", nil)
 41 | 		return cfg, true, nil
 42 | 
 43 | 	case errors.Is(err, models.ErrNotFound):
 44 | 		if !s.cfg.TwoFARequired {
 45 | 			return nil, false, nil
 46 | 		}
 47 | 		now := s.now()
 48 | 		cfg = &models.TwoFactorConfig{
 49 | 			ID:          ids.New(),
 50 | 			AdminID:     admin.ID,
 51 | 			Method:      models.TwoFAMethodEmailOTP,
 52 | 			IsEnabled:   true,
 53 | 			ConfirmedAt: &now,
 54 | 			CreatedAt:   now,
 55 | 		}
 56 | 		if err := s.twoFA.Upsert(ctx, cfg); err != nil {
 57 | 			return nil, false, err
 58 | 		}
 59 | 		s.auditEvent(ctx, admin.ID, models.AuditTwoFAEnabled, "auto_provisioned", nil)
 60 | 		return cfg, true, nil
 61 | 
 62 | 	default:
 63 | 		return nil, false, err
 64 | 	}
 65 | }
 66 | 
 67 | // TwoFAStatus reports the effective 2FA state: Enabled is true when the
 68 | // second factor is required either by server policy or by the admin setting.
 69 | func (s *AuthService) TwoFAStatus(ctx context.Context, admin *models.AdminUser) (*TwoFAStatus, error) {
 70 | 	status := &TwoFAStatus{
 71 | 		Required: s.cfg.TwoFARequired,
 72 | 		Method:   models.TwoFAMethodEmailOTP,
 73 | 		Email:    security.MaskEmail(admin.Email),
 74 | 	}
 75 | 
 76 | 	cfg, err := s.twoFA.FindByAdminAndMethod(ctx, admin.ID, models.TwoFAMethodEmailOTP)
 77 | 	if err != nil {
 78 | 		if errors.Is(err, models.ErrNotFound) {
 79 | 			status.Enabled = s.cfg.TwoFARequired
 80 | 			return status, nil
 81 | 		}
 82 | 		return nil, err
 83 | 	}
 84 | 
 85 | 	status.Enabled = cfg.IsEnabled || s.cfg.TwoFARequired
 86 | 	status.ConfirmedAt = cfg.ConfirmedAt
 87 | 	created := cfg.CreatedAt
 88 | 	status.UpdatedAt = &created
 89 | 	return status, nil
 90 | }
 91 | 
 92 | // TwoFAStatusByAdminID is the handler-friendly variant of TwoFAStatus.
 93 | func (s *AuthService) TwoFAStatusByAdminID(ctx context.Context, adminID string) (*TwoFAStatus, error) {
 94 | 	admin, err := s.adminFor(ctx, adminID)
 95 | 	if err != nil {
 96 | 		return nil, err
 97 | 	}
 98 | 	return s.TwoFAStatus(ctx, admin)
 99 | }
100 | 
101 | // EnableEmailOTP turns the email second factor on (password re-confirmation
102 | // required) and returns the fresh status.
103 | func (s *AuthService) EnableEmailOTP(ctx context.Context, adminID string, in PasswordConfirmationInput) (*TwoFAStatus, error) {
104 | 	admin, err := s.verifyAdminPassword(ctx, adminID, in.Password)
105 | 	if err != nil {
106 | 		return nil, err
107 | 	}
108 | 
109 | 	now := s.now()
110 | 	cfg := &models.TwoFactorConfig{
111 | 		ID:          ids.New(),
112 | 		AdminID:     admin.ID,
113 | 		Method:      models.TwoFAMethodEmailOTP,
114 | 		IsEnabled:   true,
115 | 		ConfirmedAt: &now,
116 | 		CreatedAt:   now,
117 | 	}
118 | 	if err := s.twoFA.Upsert(ctx, cfg); err != nil {
119 | 		return nil, err
120 | 	}
121 | 	s.auditEvent(ctx, admin.ID, models.AuditTwoFAEnabled, "admin_setting", nil)
122 | 	return s.TwoFAStatus(ctx, admin)
123 | }
124 | 
125 | // DisableEmailOTP turns the second factor off. It refuses when the server
126 | // enforces 2FA (AUTH_2FA_REQUIRED=true) so a compromised session cannot strip
127 | // the protection.
128 | func (s *AuthService) DisableEmailOTP(ctx context.Context, adminID string, in PasswordConfirmationInput) error {
129 | 	if s.cfg.TwoFARequired {
130 | 		return errTwoFAEnforced()
131 | 	}
132 | 
133 | 	admin, err := s.verifyAdminPassword(ctx, adminID, in.Password)
134 | 	if err != nil {
135 | 		return err
136 | 	}
137 | 
138 | 	if err := s.twoFA.SetEnabled(ctx, admin.ID, models.TwoFAMethodEmailOTP, false, s.now()); err != nil {
139 | 		if errors.Is(err, models.ErrNotFound) {
140 | 			return errTwoFANotConfigured()
141 | 		}
142 | 		return err
143 | 	}
144 | 	s.auditEvent(ctx, admin.ID, models.AuditTwoFADisabled, "admin_setting", nil)
145 | 	return nil
146 | }
147 | 
148 | // verifyAdminPassword re-authenticates a signed-in admin for sensitive actions.
149 | func (s *AuthService) verifyAdminPassword(ctx context.Context, adminID, password string) (*models.AdminUser, error) {
150 | 	admin, err := s.admins.FindByID(ctx, adminID)
151 | 	if err != nil {
152 | 		if errors.Is(err, models.ErrNotFound) {
153 | 			return nil, errInvalidCredentials()
154 | 		}
155 | 		return nil, err
156 | 	}
157 | 	if !admin.IsActive {
158 | 		return nil, errAccountDisabled()
159 | 	}
160 | 	if password == "" {
161 | 		return nil, errInvalidPassword()
162 | 	}
163 | 
164 | 	ok, err := security.VerifyPassword(admin.PasswordHash, password)
165 | 	if err != nil {
166 | 		return nil, wrapErr(err, 500, "internal_error", "Stored credentials are unreadable.")
167 | 	}
168 | 	if !ok {
169 | 		log.Printf("⚠️  auth: password re-confirmation failed for admin %s", admin.ID)
170 | 		return nil, errInvalidPassword()
171 | 	}
172 | 	return admin, nil
173 | }

  1 | // Command adminctl bootstraps and maintains admin accounts directly in Turso.
  2 | // It is the only way to create the first admin, since the public API has no
  3 | // sign-up endpoint.
  4 | //
  5 | // Usage (run from the repository root so .env is picked up):
  6 | //
  7 | //	go run ./cmd/adminctl -action=create -username=kamlesh -email=me@example.com -password='...'
  8 | //	go run ./cmd/adminctl -action=list
  9 | //	go run ./cmd/adminctl -action=reset-password -username=kamlesh
 10 | //	go run ./cmd/adminctl -action=enable-2fa -username=kamlesh
 11 | //	go run ./cmd/adminctl -action=disable-2fa -username=kamlesh   # emergency unlock
 12 | //	go run ./cmd/adminctl -action=deactivate -username=kamlesh
 13 | //
 14 | // Tip: omit -password and it is read from stdin instead, which keeps it out of
 15 | // your shell history:  echo 'my-secret-passphrase 1' | go run ./cmd/adminctl ...
 16 | package main
 17 | 
 18 | import (
 19 | 	"bufio"
 20 | 	"context"
 21 | 	"errors"
 22 | 	"flag"
 23 | 	"fmt"
 24 | 	"log"
 25 | 	"net/mail"
 26 | 	"os"
 27 | 	"strings"
 28 | 	"time"
 29 | 
 30 | 	"github.com/coderkamlesh/portfolio_api/internal/database"
 31 | 	"github.com/coderkamlesh/portfolio_api/internal/models"
 32 | 	"github.com/coderkamlesh/portfolio_api/internal/pkg/ids"
 33 | 	"github.com/coderkamlesh/portfolio_api/internal/repository"
 34 | 	"github.com/coderkamlesh/portfolio_api/internal/security"
 35 | 	"github.com/joho/godotenv"
 36 | )
 37 | 
 38 | func main() {
 39 | 	log.SetFlags(0)
 40 | 
 41 | 	action := flag.String("action", "create",
 42 | 		"one of: create, list, reset-password, activate, deactivate, enable-2fa, disable-2fa")
 43 | 	username := flag.String("username", "", "admin username")
 44 | 	email := flag.String("email", "", "admin email (required for create)")
 45 | 	password := flag.String("password", "", "admin password (omit to read it from stdin)")
 46 | 	flag.Parse()
 47 | 
 48 | 	if err := godotenv.Load(); err != nil {
 49 | 		log.Println("No .env file found, using environment variables")
 50 | 	}
 51 | 	url, token := os.Getenv("TURSO_DATABASE_URL"), os.Getenv("TURSO_AUTH_TOKEN")
 52 | 	if url == "" || token == "" {
 53 | 		log.Fatal("❌ TURSO_DATABASE_URL and TURSO_AUTH_TOKEN must be set")
 54 | 	}
 55 | 
 56 | 	ctx := context.Background()
 57 | 	db, err := database.Connect(url, token)
 58 | 	if err != nil {
 59 | 		log.Fatalf("❌ DB connect failed: %v", err)
 60 | 	}
 61 | 	defer db.Close()
 62 | 
 63 | 	admins := repository.NewAdminRepository(db)
 64 | 	twoFA := repository.NewTwoFARepository(db)
 65 | 
 66 | 	if err := run(ctx, *action, admins, twoFA, *username, *email, *password); err != nil {
 67 | 		log.Fatalf("❌ %s: %v", *action, err)
 68 | 	}
 69 | }
 70 | 
 71 | // run dispatches the requested action.
 72 | func run(ctx context.Context, action string, admins *repository.AdminRepository,
 73 | 	twoFA *repository.TwoFARepository, username, email, password string) error {
 74 | 
 75 | 	switch action {
 76 | 	case "create":
 77 | 		return createAdmin(ctx, admins, username, email, password)
 78 | 	case "list":
 79 | 		return listAdmins(ctx, admins)
 80 | 	case "reset-password":
 81 | 		return resetPassword(ctx, admins, username, password)
 82 | 	case "activate", "deactivate":
 83 | 		return setActive(ctx, admins, username, action == "activate")
 84 | 	case "enable-2fa", "disable-2fa":
 85 | 		return setTwoFA(ctx, twoFA, admins, username, action == "enable-2fa")
 86 | 	default:
 87 | 		return fmt.Errorf("unknown -action %q", action)
 88 | 	}
 89 | }
 90 | 
 91 | // createAdmin inserts a new admin (or resets the credentials of an existing
 92 | // username, making the command idempotent for provisioning scripts).
 93 | func createAdmin(ctx context.Context, admins *repository.AdminRepository, username, email, password string) error {
 94 | 	username = strings.TrimSpace(username)
 95 | 	email = strings.ToLower(strings.TrimSpace(email))
 96 | 	if username == "" {
 97 | 		return errors.New("-username is required")
 98 | 	}
 99 | 	if _, err := mail.ParseAddress(email); err != nil {
100 | 		return fmt.Errorf("-email must be a valid address: %w", err)
101 | 	}
102 | 
103 | 	password, err := resolvePassword(password)
104 | 	if err != nil {
105 | 		return err
106 | 	}
107 | 	if err := security.ValidatePassword(password, 12); err != nil {
108 | 		return fmt.Errorf("weak password (must %s)", err)
109 | 	}
110 | 
111 | 	hash, err := security.HashPassword(password)
112 | 	if err != nil {
113 | 		return err
114 | 	}
115 | 
116 | 	now := time.Now().UTC()
117 | 	account := &models.AdminUser{
118 | 		ID:           ids.New(),
119 | 		Username:     username,
120 | 		Email:        email,
121 | 		PasswordHash: hash,
122 | 		IsActive:     true,
123 | 		CreatedAt:    now,
124 | 		UpdatedAt:    now,
125 | 	}
126 | 	if err := admins.Upsert(ctx, account); err != nil {
127 | 		return err
128 | 	}
129 | 
130 | 	fmt.Printf("✅ Admin %q <%s> saved (argon2id). 2FA=EMAIL_OTP applies on login.\n", username, email)
131 | 	return nil
132 | }
133 | 
134 | // listAdmins prints every admin account.
135 | func listAdmins(ctx context.Context, admins *repository.AdminRepository) error {
136 | 	accounts, err := admins.List(ctx)
137 | 	if err != nil {
138 | 		return err
139 | 	}
140 | 	if len(accounts) == 0 {
141 | 		fmt.Println("ℹ️  No admin accounts yet. Create one with -action=create.")
142 | 		return nil
143 | 	}
144 | 
145 | 	fmt.Printf("%-38s %-16s %-30s %-8s %s\n", "ID", "USERNAME", "EMAIL", "ACTIVE", "LAST LOGIN")
146 | 	for _, a := range accounts {
147 | 		lastLogin := "never"
148 | 		if a.LastLoginAt != nil {
149 | 			lastLogin = a.LastLoginAt.UTC().Format(time.RFC3339)
150 | 		}
151 | 		fmt.Printf("%-38s %-16s %-30s %-8t %s\n", a.ID, a.Username, a.Email, a.IsActive, lastLogin)
152 | 	}
153 | 	return nil
154 | }
155 | 
156 | // resetPassword rotates the password of an existing admin.
157 | func resetPassword(ctx context.Context, admins *repository.AdminRepository, username, password string) error {
158 | 	account, err := findAdmin(ctx, admins, username)
159 | 	if err != nil {
160 | 		return err
161 | 	}
162 | 
163 | 	password, err = resolvePassword(password)
164 | 	if err != nil {
165 | 		return err
166 | 	}
167 | 	if err := security.ValidatePassword(password, 12); err != nil {
168 | 		return fmt.Errorf("weak password (must %s)", err)
169 | 	}
170 | 
171 | 	hash, err := security.HashPassword(password)
172 | 	if err != nil {
173 | 		return err
174 | 	}
175 | 	if err := admins.UpdatePassword(ctx, account.ID, hash, time.Now().UTC()); err != nil {
176 | 		return err
177 | 	}
178 | 	fmt.Printf("✅ Password updated for %q. Existing sessions die on their next refresh.\n", account.Username)
179 | 	return nil
180 | }
181 | 
182 | // setActive enables or disables an account.
183 | func setActive(ctx context.Context, admins *repository.AdminRepository, username string, active bool) error {
184 | 	account, err := findAdmin(ctx, admins, username)
185 | 	if err != nil {
186 | 		return err
187 | 	}
188 | 	if err := admins.SetActive(ctx, account.ID, active, time.Now().UTC()); err != nil {
189 | 		return err
190 | 	}
191 | 	fmt.Printf("✅ %q is_active=%t\n", account.Username, active)
192 | 	return nil
193 | }
194 | 
195 | // setTwoFA flips the EMAIL_OTP row so an admin can be unlocked out-of-band when
196 | // SES or the mailbox is unavailable.
197 | func setTwoFA(ctx context.Context, twoFA *repository.TwoFARepository, admins *repository.AdminRepository,
198 | 	username string, enabled bool) error {
199 | 
200 | 	account, err := findAdmin(ctx, admins, username)
201 | 	if err != nil {
202 | 		return err
203 | 	}
204 | 
205 | 	if !enabled {
206 | 		if err := twoFA.SetEnabled(ctx, account.ID, models.TwoFAMethodEmailOTP, false, time.Now().UTC()); err != nil {
207 | 			if errors.Is(err, models.ErrNotFound) {
208 | 				fmt.Printf("ℹ️  %q has no 2FA row to disable.\n", account.Username)
209 | 				return nil
210 | 			}
211 | 			return err
212 | 		}
213 | 		fmt.Printf("⚠️  Email OTP disabled for %q. Re-enable before exposing the panel!\n", account.Username)
214 | 		return nil
215 | 	}
216 | 
217 | 	now := time.Now().UTC()
218 | 	if err := twoFA.Upsert(ctx, &models.TwoFactorConfig{
219 | 		ID:          ids.New(),
220 | 		AdminID:     account.ID,
221 | 		Method:      models.TwoFAMethodEmailOTP,
222 | 		IsEnabled:   true,
223 | 		ConfirmedAt: &now,
224 | 		CreatedAt:   now,
225 | 	}); err != nil {
226 | 		return err
227 | 	}
228 | 	fmt.Printf("✅ Email OTP 2FA enabled for %q.\n", account.Username)
229 | 	return nil
230 | }
231 | 
232 | // findAdmin resolves -username or -email to an account.
233 | func findAdmin(ctx context.Context, admins *repository.AdminRepository, identifier string) (*models.AdminUser, error) {
234 | 	identifier = strings.TrimSpace(identifier)
235 | 	if identifier == "" {
236 | 		return nil, errors.New("-username (or -email) is required")
237 | 	}
238 | 
239 | 	account, err := admins.FindByIdentifier(ctx, identifier)
240 | 	if err != nil {
241 | 		if errors.Is(err, models.ErrNotFound) {
242 | 			return nil, fmt.Errorf("no admin found for %q", identifier)
243 | 		}
244 | 		return nil, err
245 | 	}
246 | 	return account, nil
247 | }
248 | 
249 | // resolvePassword returns the -password flag value, or reads one line from
250 | // stdin so the password never has to appear in the shell history.
251 | func resolvePassword(flagValue string) (string, error) {
252 | 	if flagValue != "" {
253 | 		return flagValue, nil
254 | 	}
255 | 
256 | 	fmt.Fprint(os.Stderr, "Password (echoed by your terminal; pipe it in to keep it out of history): ")
257 | 	reader := bufio.NewReader(os.Stdin)
258 | 	line, err := reader.ReadString('\n')
259 | 	if err != nil && line == "" {
260 | 		return "", fmt.Errorf("could not read password from stdin: %w", err)
261 | 	}
262 | 	password := strings.TrimRight(line, "\r\n")
263 | 	if password == "" {
264 | 		return "", errors.New("password must not be empty")
265 | 	}
266 | 	return password, nil
267 | }

